//! Passes `wsock32.def` (generated by `tools/gen_def.py`, committed) to the linker
//! when the cdylib is built for 32-bit Windows. The `.def` reproduces every export of
//! the system `SysWOW64\wsock32.dll` with the same name and ordinal; rustc's own
//! export list is overridden because lld uses the last `/def` it is given and
//! `-C link-arg`s come after rustc's arguments.
//!
//! Other targets (the x86_64 host, where only the unit tests run) get no `.def`.

use std::env;
use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=wsock32.def");

    let os = env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let arch = env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    if os != "windows" || arch != "x86" {
        return;
    }
    let Some(dir) = env::var_os("CARGO_MANIFEST_DIR") else {
        println!("cargo:warning=CARGO_MANIFEST_DIR unset; wsock32.def not applied");
        return;
    };
    let def = PathBuf::from(dir).join("wsock32.def");
    println!("cargo:rustc-cdylib-link-arg={}", def.display());
}
